<?php
session_start();if(empty($_SESSION['usuario_id'])||($_SESSION['usuario_rol']??'')!=='admin'){header('Location: ../index.php');exit;}require_once __DIR__.'/../backend/conexion.php';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$estado=$_POST['estado']??'';if($id&&in_array($estado,['publicada','rechazada'],true)){$q=$pdo->prepare('UPDATE resenas SET estado=? WHERE id=?');$q->execute([$estado,$id]);}}$rows=$pdo->query('SELECT r.*,u.nombre,p.nombre producto FROM resenas r JOIN usuarios u ON u.id=r.usuario_id JOIN productos p ON p.id=r.producto_id ORDER BY r.id DESC')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reseñas</title><style>body{font:15px Arial;background:#f4f6f8;margin:0}.top{background:#17191d;color:white;padding:18px 5%}.top a{color:white}.wrap{max-width:1100px;margin:28px auto;padding:0 18px}section{background:white;padding:18px;border-radius:12px;overflow:auto}table{width:100%;border-collapse:collapse;min-width:700px}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}button{padding:8px;border:0;border-radius:7px;background:#e53935;color:white}</style></head><body><header class="top"><b>Mi Store · Reseñas</b>　<a href="index.php">Panel</a></header><main class="wrap"><h1>Moderación de reseñas</h1><section><table><tr><th>Cliente</th><th>Producto</th><th>Calificación</th><th>Comentario</th><th>Estado</th><th>Acción</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nombre'])?></td><td><?=htmlspecialchars($r['producto'])?></td><td><?=$r['calificacion']?>/5</td><td><?=nl2br(htmlspecialchars($r['comentario']??''))?></td><td><?=$r['estado']?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="estado" value="publicada">Publicar</button> <button name="estado" value="rechazada">Rechazar</button></form></td></tr><?php endforeach?></table></section></main></body></html>
